   </div>
   <footer class="footer"><span><strong>MAGNETAR</strong> &nbsp; // &nbsp; A COSMIC COLLECTION GAME</span><span>NO. 07 — KEEP YOUR DISTANCE</span></footer>
 </main>
 <script>
+(()=>{
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+const W=960,H=600, goal=12;
+const $=id=>document.getElementById(id);
+const overlay=$('overlay'),keys=new Set(),touch=new Set();
+let state='ready',last=0,time=0,score=0,lives=3,charge=100,magnet=false,soundOn=false,audio=null,shake=0;
+let player,shards=[],enemies=[],particles=[],stars=[],fieldPulse=0;
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
+function init(){
+ player={x:W/2,y:H/2,vx:0,vy:0,r:13,inv:0,trail:[]};shards=[];enemies=[];particles=[];score=0;lives=3;charge=100;time=0;shake=0;fieldPulse=0;
+ for(let i=0;i<80;i++)stars.push({x:rand(20,W-20),y:rand(20,H-20),r:rand(.5,1.8),a:rand(.16,.62),p:rand(0,6)});
+ for(let i=0;i<5;i++)spawnShard();
+ spawnEnemy(0);spawnEnemy(1);updateHud();
+}
+function spawnShard(){let p;for(let tries=0;tries<40;tries++){p={x:rand(70,W-70),y:rand(70,H-70),vx:rand(-20,20),vy:rand(-20,20),r:7,spin:rand(0,6),glow:rand(0,6)};if(!player||Math.hypot(p.x-player.x,p.y-player.y)>130)break;}shards.push(p);}
+function spawnEnemy(index){let angle=rand(0,Math.PI*2),dist=rand(270,390);enemies.push({x:clamp(player.x+Math.cos(angle)*dist,55,W-55),y:clamp(player.y+Math.sin(angle)*dist,55,H-55),vx:0,vy:0,r:15,speed:rand(39,53)+score*1.1,phase:rand(0,7),stun:0,hit:0,id:index});}
+function updateHud(){ $('score').innerHTML=String(score).padStart(2,'0')+'<span style="color:#666579">/12</span>'; $('progress').style.width=(score/goal*100)+'%';$('wave').textContent=String(Math.floor(score/4)+1).padStart(2,'0');$('lives').textContent=('♥ '.repeat(lives)).trim()||'—';$('chargeNum').textContent=Math.round(charge)+'%';$('magnetState').textContent=magnet?'ENGAGED':charge<15?'RECHARGING':'READY';$('magnetState').style.color=magnet?'#6cf4e2':'';let bars=$('charge');bars.innerHTML='';for(let i=0;i<10;i++){let b=document.createElement('i');if(charge>=((i+1)*10)-1)b.className='full';bars.appendChild(b);}}
+function start(){if(state==='playing')return;init();state='playing';overlay.classList.add('hidden');$('pauseBtn').innerHTML='Ⅱ &nbsp; PAUSE';last=performance.now();}
+function end(win){state=win?'won':'lost';magnet=false;overlay.classList.remove('hidden');$('overline').textContent=win?'FIELD STABLE · MISSION COMPLETE':'SIGNAL LOST · FIELD COLLAPSE';$('title').innerHTML=win?'YOU<br/><em>GOT THEM</em>':'FIELD<br/><em>COLLAPSED</em>';$('message').innerHTML=win?`All <strong>${goal} shards</strong> secured. The little stars are safe with you.`:`You gathered <strong>${score} of ${goal} shards</strong>. The field always gives you another shot.`;$('playBtn').textContent='RUN IT BACK  →';$('hint').textContent='PRESS ENTER OR CLICK TO TRY AGAIN';$('pauseBtn').innerHTML='Ⅱ &nbsp; PAUSE';}
+function pause(){if(state==='playing'){state='paused';magnet=false;overlay.classList.remove('hidden');$('overline').textContent='FLIGHT PAUSED';$('title').innerHTML='TAKE A<br/><em>BREATHER</em>';$('message').textContent='The stars can wait. Take a breath, then get back out there.';$('playBtn').textContent='RESUME FLIGHT  →';$('hint').textContent='PRESS P OR ESC TO RESUME';$('pauseBtn').innerHTML='▶ &nbsp; RESUME';}else if(state==='paused'){state='playing';overlay.classList.add('hidden');$('pauseBtn').innerHTML='Ⅱ &nbsp; PAUSE';last=performance.now();}}
+function sound(freq=560,dur=.09,type='sine'){if(!soundOn)return;try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.055,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur);}catch(e){}}
+function burst(x,y,color,n=12){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(35,180);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.3,.75),max:.75,r:rand(1.5,4),color});}}
+function input(){let x=0,y=0;if(keys.has('ArrowLeft')||keys.has('a')||touch.has('left'))x--;if(keys.has('ArrowRight')||keys.has('d')||touch.has('right'))x++;if(keys.has('ArrowUp')||keys.has('w')||touch.has('up'))y--;if(keys.has('ArrowDown')||keys.has('s')||touch.has('down'))y++;let m=Math.hypot(x,y);if(m){x/=m;y/=m;}return{x,y,pull:(keys.has(' ')||touch.has('pull'))&&charge>0};}
+function update(dt){time+=dt;let inp=input();magnet=inp.pull;if(magnet){charge=Math.max(0,charge-dt*28);fieldPulse+=dt*3;}else charge=Math.min(100,charge+dt*19);if(charge===0)magnet=false;
+ const accel=750,drag=Math.pow(.0009,dt),max=220;player.vx=(player.vx+inp.x*accel*dt)*drag;player.vy=(player.vy+inp.y*accel*dt)*drag;let sp=Math.hypot(player.vx,player.vy);if(sp>max){player.vx*=max/sp;player.vy*=max/sp;}player.x=clamp(player.x+player.vx*dt,35,W-35);player.y=clamp(player.y+player.vy*dt,35,H-35);player.inv=Math.max(0,player.inv-dt);player.trail.push({x:player.x,y:player.y,a:1});if(player.trail.length>8)player.trail.shift();
+ for(let i=shards.length-1;i>=0;i--){let s=shards[i];s.spin+=dt*1.4;s.glow+=dt*2;s.vx*=Math.pow(.985,dt*60);s.vy*=Math.pow(.985,dt*60);if(magnet){let dx=player.x-s.x,dy=player.y-s.y,d=Math.hypot(dx,dy)||1;if(d<270){let force=(1-d/300)*850;s.vx+=dx/d*force*dt;s.vy+=dy/d*force*dt;}}s.vx=clamp(s.vx,-210,210);s.vy=clamp(s.vy,-210,210);s.x+=s.vx*dt;s.y+=s.vy*dt;if(s.x<45||s.x>W-45)s.vx*=-.8;if(s.y<45||s.y>H-45)s.vy*=-.8;if(Math.hypot(s.x-player.x,s.y-player.y)<s.r+player.r+3){shards.splice(i,1);score++;burst(s.x,s.y,'#6cf4e2',15);sound(690+score*25,.12,'triangle');if(score>=goal){updateHud();end(true);return;}spawnShard();if(score%4===0)spawnEnemy(enemies.length);updateHud();}}
+ for(let e of enemies){e.phase+=dt*3;e.hit=Math.max(0,e.hit-dt);e.stun=Math.max(0,e.stun-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;let force=e.stun?0:e.speed;if(magnet&&d<180){force=-100;e.stun=Math.max(e.stun,.04);}e.vx+=dx/d*force*dt;e.vy+=dy/d*force*dt;e.vx*=Math.pow(.24,dt);e.vy*=Math.pow(.24,dt);e.x=clamp(e.x+e.vx*dt,42,W-42);e.y=clamp(e.y+e.vy*dt,42,H-42);if(magnet&&d<180&&e.hit<=0){e.hit=.22;burst(e.x,e.y,'#ff779a',2);}if(!player.inv&&d<e.r+player.r){lives--;player.inv=1.5;shake=12;let a=Math.atan2(player.y-e.y,player.x-e.x);player.vx=Math.cos(a)*300;player.vy=Math.sin(a)*300;burst(player.x,player.y,'#ff779a',18);sound(150,.22,'sawtooth');updateHud();if(lives<=0){end(false);return;}}}
+ for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);if(p.life<=0)particles.splice(i,1);}shake=Math.max(0,shake-dt*35);if(Math.floor(time*5)!==Math.floor((time-dt)*5))updateHud();}

input.newString:
 for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);if(p.life<=0)particles.splice(i,1);}shake=Math.max(0,shake-dt*35);if(Math.floor(time*5)!==Math.floor((time-dt)*5))updateHud();}
function draw(){ctx.save();if(shake)ctx.translate(rand(-shake,shake),rand(-shake,shake));let bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#10101d');bg.addColorStop(.55,'#11101e');bg.addColorStop(1,'#0c101b');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
 let glow=ctx.createRadialGradient(W/2,H/2,20,W/2,H/2,530);glow.addColorStop(0,'#29203d55');glow.addColorStop(1,'#10101d00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
 for(let x=40;x<W;x+=40){ctx.strokeStyle=x%200===0?'#aaa0ff0c':'#aaa0ff06';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,30);ctx.lineTo(x,H-30);ctx.stroke();}for(let y=40;y<H;y+=40){ctx.strokeStyle=y%200===0?'#aaa0ff0c':'#aaa0ff06';ctx.beginPath();ctx.moveTo(30,y);ctx.lineTo(W-30,y);ctx.stroke();}
 for(let s of stars){let a=s.a*(.72+.28*Math.sin(time*1.6+s.p));ctx.fillStyle=`rgba(216,218,255,${a})`;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();}
 ctx.strokeStyle='#8581ae20';ctx.lineWidth=1;ctx.setLineDash([4,8]);ctx.strokeRect(30,30,W-60,H-60);ctx.setLineDash([]);
 if(magnet&&state==='playing'){let r=270+Math.sin(fieldPulse*2)*8;let g=ctx.createRadialGradient(player.x,player.y,20,player.x,player.y,r);g.addColorStop(0,'#6cf4e21a');g.addColorStop(.72,'#6cf4e20b');g.addColorStop(1,'#6cf4e200');ctx.fillStyle=g;ctx.beginPath();ctx.arc(player.x,player.y,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#6cf4e253';ctx.setLineDash([5,9]);ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(player.x,player.y,r,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);}
 for(let s of shards){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(s.spin);ctx.shadowBlur=17;ctx.shadowColor='#6cf4e2';ctx.fillStyle='#6cf4e2';ctx.beginPath();ctx.moveTo(0,-s.r-2);ctx.lineTo(s.r*.72,0);ctx.lineTo(0,s.r+2);ctx.lineTo(-s.r*.72,0);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#e7fff9';ctx.fillRect(-1,-3,2,6);ctx.restore();ctx.beginPath();ctx.strokeStyle='#6cf4e220';ctx.lineWidth=1;ctx.arc(s.x,s.y,15+Math.sin(s.glow)*2,0,Math.PI*2);ctx.stroke();}
 for(let e of enemies){ctx.save();ctx.translate(e.x,e.y);let pulse=1+Math.sin(e.phase)*.055;ctx.scale(pulse,pulse);ctx.shadowBlur=16;ctx.shadowColor=e.stun?'#ffb8cb':'#ff779a';ctx.strokeStyle=e.stun?'#ffd3df':'#ff779a';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<8;i++){let a=i*Math.PI/4-Math.PI/8,r=i%2?e.r*.82:e.r*1.18;let x=Math.cos(a)*r,y=Math.sin(a)*r;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.closePath();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#ff779a24';ctx.fill();ctx.fillStyle='#ffd2dd';ctx.beginPath();ctx.arc(0,0,3.3,0,Math.PI*2);ctx.fill();ctx.restore();}
 for(let p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.shadowBlur=10;ctx.shadowColor=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;ctx.shadowBlur=0;
 for(let i=0;i<player.trail.length;i++){let t=player.trail[i],a=(i/player.trail.length)*.18;if(player.inv&&Math.floor(time*16)%2)continue;ctx.fillStyle=`rgba(108,244,226,${a})`;ctx.beginPath();ctx.arc(t.x,t.y,player.r*(i/player.trail.length),0,Math.PI*2);ctx.fill();}
 if(!(player.inv&&Math.floor(time*16)%2)){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(Math.atan2(player.vy,player.vx)+Math.PI/2);ctx.shadowBlur=23;ctx.shadowColor='#6cf4e2';ctx.fillStyle='#6cf4e2';ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(12,12);ctx.lineTo(0,7);ctx.lineTo(-12,12);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#102222';ctx.beginPath();ctx.arc(0,0,4,0,Math.PI*2);ctx.fill();ctx.restore();}
 // Small corner coordinates and objective marker
 ctx.fillStyle='#77748c';ctx.font='10px monospace';ctx.fillText('SECTOR 07 / '+String(Math.floor(time/30)+1).padStart(2,'0'),46,52);ctx.textAlign='right';ctx.fillText('SHARDS '+String(score).padStart(2,'0')+' / '+goal,W-46,52);ctx.textAlign='left';
 ctx.restore();}
function frame(now){let dt=Math.min(.034,(now-last)/1000||0);last=now;if(state==='playing')update(dt);draw();requestAnimationFrame(frame);}
$('playBtn').addEventListener('click',()=>state==='paused'?pause():start());$('pauseBtn').addEventListener('click',pause);
$('soundBtn').addEventListener('click',()=>{soundOn=!soundOn;$('soundBtn').textContent=soundOn?'♪ SOUND ON':'♪ SOUND OFF';if(soundOn)sound(520,.08);});
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='enter'&&(state==='ready'||state==='won'||state==='lost'))start();else if(k==='enter'&&state==='paused')pause();else if(k==='p'||k==='escape')pause();else if(k==='r'){if(state!=='ready')start();}});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();touch.clear();if(state==='playing')pause();});
document.querySelectorAll('[data-dir]').forEach(btn=>{let dir=btn.dataset.dir;btn.addEventListener('pointerdown',e=>{e.preventDefault();touch.add(dir);btn.setPointerCapture(e.pointerId);});for(let type of ['pointerup','pointercancel','lostpointercapture'])btn.addEventListener(type,()=>touch.delete(dir));});
let mt=$('magnetTouch');mt.addEventListener('pointerdown',e=>{e.preventDefault();touch.add('pull');mt.classList.add('active');mt.setPointerCapture(e.pointerId);});for(let type of ['pointerup','pointercancel','lostpointercapture'])mt.addEventListener(type,()=>{touch.delete('pull');mt.classList.remove('active');});
init();requestAnimationFrame(t=>{last=t;frame(t);});
})();
</script>
</body>
</html>

